68	/**
69	 * For every plan on the sheet in the order they were added, adds a DRAFT claim of the plan's amount, dated that
70	 * day with an empty note, for every plan date (the start, then every N days, or a monthly plan's day in each month) up to its end and the sheet's today
71	 * that it has made none for yet, as the claim form would (recorded as CLAIM_ADDED). A date the claim form refuses
72	 * is skipped, and tried again on the next generate. A viewer makes none: the answer is 0, storing and recording nothing.
73	 */
74	public class GeneratePlanClaims {
75	    public void generate(@PathVariable("sheetId") String sheetId, @Val PlanGenerateRequest request, PlanStore plans,
76	            PersonStore people, SheetStore sheets, ClaimStore claims, SettingStore settings, ClaimLogStore log,
77	            PeriodStore periods, RollupService rollups, Audit audit, HolidayStore holidays, RoleStore roles,
78	            Out<PlanGenerateResult> result) {
79	        String sheet = sheetId.trim();
80	        LocalDate today = sheets.today(sheet);
81	        int made = 0;
82	        if (roles.find(sheet, request.user()) == Role.VIEWER) {
83	            result.set(new PlanGenerateResult(made));
84	            return;
85	        }
86	        for (Plan plan : plans.list(sheet)) {
87	            LocalDate last = plan.end().isBefore(today) ? plan.end() : today;
88	            for (LocalDate d : plan.dates(last)) {
89	                if (plans.made(plan.id(), d)) {
90	                    continue;
91	                }
92	                Person person = people.find(sheet, plan.personId());
93	                if (person == null) {
94	                    break;
95	                }
96	                ClaimInput input;
97	                try {
98	                    input = ClaimAdding.check(sheet, person, new ClaimRequest(plan.amount().toPlainString(),
99	                            d.toString(), "", request.user(), "", ""), settings, periods, claims, holidays);
100	                } catch (InvalidSheetException e) {
101	                    continue;
102	                }
103	                ClaimAdding.add(input, person, claims, settings, log, periods, rollups, audit, holidays);
104	                plans.markMade(plan.id(), d);
105	                made++;
106	            }
107	        }
108	        result.set(new PlanGenerateResult(made));
109	    }
110	}
