215	/** A person's plan: a DRAFT claim of the amount on every plan date up to the end; {@code generated} how many
216	 *  claims it has made so far. The plan dates are the start then every {@code every} days, or, for a monthly plan
217	 *  ({@code day} set, {@code every} null), {@link #dates(LocalDate)}. A date one of its {@code pauses} skips is
218	 *  left out of them. {@code amount} is the latest of its {@code changes}, oldest first, if any. */
219	public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
220	        Integer day, LocalDate end, int generated, List<PlanPause> pauses,
221	        List<PlanChange> changes) {
222	
223	    /** Whether the plan is paused now: a pause not yet resumed. */
224	    public boolean paused() {
225	        return pauses.stream().anyMatch(p -> p.resumed() == null);
226	    }
227	
228	    private boolean skipped(LocalDate date) {
229	        return pauses.stream().anyMatch(p -> p.skips(date));
230	    }
231	
232	    /** The plan dates up to and including {@code last}, in order. A monthly plan's are its day in every month
233	     *  from the start's month, a day beyond the month's length falling on its last day, those before the start
234	     *  left out. Those a pause skips are left out too. */
235	    public List<LocalDate> dates(LocalDate last) {
236	        List<LocalDate> dates = new ArrayList<>();
237	        if (day == null) {
238	            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
239	                if (!skipped(d)) {
240	                    dates.add(d);
241	                }
242	            }
243	            return dates;
244	        }
245	        for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
246	            LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
247	            if (!d.isBefore(start) && !d.isAfter(last) && !skipped(d)) {
248	                dates.add(d);
249	            }
250	        }
251	        return dates;
252	    }
253	
254	    /** The first {@code count} plan dates after {@code today} and on or before the end, in order; none while
255	     *  the plan is paused. */
256	    public List<LocalDate> nextDates(LocalDate today, int count) {
257	        if (paused()) {
258	            return List.of();
259	        }
260	        return dates(end).stream().filter(d -> d.isAfter(today)).limit(count).toList();
