515	/** Refuses a plan by a viewer, with an amount the claim form would refuse for a claim made from it (one that is
516	 *  not a number with up to two decimals, or a negative one), an interval that is not a whole number of at least
517	 *  1, a day of the month that is not a whole number from 1 to 31, both an interval and a day or neither, a bad
518	 *  date or an end before the start. A blank start is the sheet's today. */
519	public class ValidatePlan {
520	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
521	    private static final Pattern EVERY = Pattern.compile("\\d{1,6}");
522	
523	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PlanRequest request,
524	            SheetStore sheets, Out<PlanInput> body, RoleStore roles) throws InvalidSheetException {
525	        String user = request == null || request.user() == null ? "" : request.user().trim();
526	        roles.refuseChange(sheetId.trim(), user);
527	        if (request == null) {
528	            throw new InvalidSheetException("A plan needs an amount, a start, an interval and an end");
529	        }
530	        String amount = request.amount() == null ? "" : request.amount().trim();
531	        if (!AMOUNT.matcher(amount).matches()) {
532	            throw new InvalidSheetException("The amount must be a number with up to two decimals");
533	        }
534	        String every = request.every() == null ? "" : request.every().trim();
535	        String day = request.day() == null ? "" : request.day().trim();
536	        if (!every.isEmpty() && !day.isEmpty()) {
537	            throw new InvalidSheetException("A plan runs either every N days or on a day of the month, not both");
538	        }
539	        Integer everyDays = null;
540	        Integer monthDay = null;
541	        if (!day.isEmpty()) {
542	            if (!EVERY.matcher(day).matches() || Integer.parseInt(day) < 1 || Integer.parseInt(day) > 31) {
543	                throw new InvalidSheetException("The day must be a day of the month from 1 to 31");
544	            }
545	            monthDay = Integer.parseInt(day);
546	        } else {
547	            if (!EVERY.matcher(every).matches() || Integer.parseInt(every) < 1) {
548	                throw new InvalidSheetException("Every must be a whole number of days, at least 1");
549	            }
550	            everyDays = Integer.parseInt(every);
551	        }
552	        String startText = request.start() == null ? "" : request.start().trim();
553	        LocalDate start = startText.isEmpty() ? sheets.today(sheetId.trim()) : date(startText);
554	        LocalDate end = date(request.end() == null ? "" : request.end().trim());
555	        if (end.isBefore(start)) {
