/** Records a plan: PLAN_ADDED sheet=<id> by=<user> name=<name> amount=<0.00> start=<date> every=<n> end=<date>, or
 *  for a monthly plan ... start=<date> day=<day> end=<date>. */
public class AuditPlanAdded {
