    public List<String> wholeTree(String sheetId) {
        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
        String root = sheetId;
        for (String at = parent(sheetId); at != null && seen.add(at); at = parent(at)) {
